use crate::binary_mapping::domain::{Framing, Investigation};
use std::fmt::Write;

fn identifier(value: &str) -> String {
    let mut output = String::from("T_");
    for character in value.chars() {
        output.push(if character.is_ascii_alphanumeric() {
            character
        } else {
            '_'
        });
        if output.len() >= 120 {
            break;
        }
    }
    output
}

pub fn render(report: &Investigation) -> String {
    let mut output = format!(
        "// Generated by wg-binary-map. Executable SHA-256: {}\n\
        // Native names are opaque metadata; wire payloads have no inferred member semantics.\n\
        #![allow(non_camel_case_types, non_snake_case)]\n\n",
        report.sha256
    );
    output.push_str("pub mod wire {\n");
    for interface in &report.interfaces {
        writeln!(output, "    pub mod {} {{", identifier(&interface.name)).unwrap();
        for message in &interface.messages {
            let name = format!("{}_{}", identifier(&message.name), message.first_id);
            writeln!(
                output,
                "        /// Registration {:#x}; handler {:#x}.",
                message.registration, message.handler
            )
            .unwrap();
            writeln!(
                output,
                "        #[derive(Debug, Clone)]\n        pub struct {name} {{"
            )
            .unwrap();
            match (&message.framing, &message.callback_length) {
                (Framing::Fixed { bytes }, _)
                | (_, Some(crate::binary_mapping::domain::CallbackLength { bytes, .. })) => {
                    writeln!(output, "            pub payload: [u8; {bytes}],").unwrap()
                }
                _ => output.push_str("            pub payload: Vec<u8>,\n"),
            }
            writeln!(output, "        }}\n        impl {name} {{\n            pub const FIRST_ID: u8 = {};\n            pub const LAST_ID: u8 = {};", message.first_id, message.last_id).unwrap();
            if let Framing::Variable { prefix_bytes } = message.framing {
                writeln!(
                    output,
                    "            pub const LENGTH_PREFIX_BYTES: usize = {prefix_bytes};"
                )
                .unwrap();
            }
            output.push_str("        }\n");
        }
        output.push_str("    }\n");
    }
    output.push_str("}\n\npub mod native {\n");
    for native in &report.native_types {
        writeln!(
            output,
            "    /// {}. Layout and size unknown; do not instantiate or use for FFI.",
            native.name.replace(['\r', '\n'], " ")
        )
        .unwrap();
        let name = format!(
            "{}_{:x}",
            identifier(&native.name),
            native.descriptor - report.image_base
        );
        writeln!(output, "    pub struct {name} {{ _opaque: [u8; 0] }}\n    impl {name} {{\n        pub const TYPE_DESCRIPTOR_VA: u64 = {:#x};\n    }}", native.descriptor).unwrap();
    }
    output.push_str("}\n");
    output
}
